-- Required delivery repair: these 20 authored Unit1/topic1.5 items had no serving labels.
create temporary table release_labels on commit drop as select t.item_id,t.new_version_id,gen_random_uuid() label_id,gen_random_uuid() decision_id from visual_targets t where t.kind='choice_repair';
insert into app.content_taxonomy_labels(content_taxonomy_label_id,content_item_id,label_version,label_scope,required_units,max_required_unit,assessed_topics,primary_unit,taxonomy_source_version,taxonomy_confidence,label_status,source,source_payload,created_by)
select r.label_id,r.item_id,coalesce((select max(l.label_version) from app.content_taxonomy_labels l where l.content_item_id=r.item_id),0)+1,'serving',array[1],1,array[]::text[],1,c.taxonomy_source_version,'verified','provisional_model','APPROVAL-0194_visual_release',jsonb_build_object('basis','existing authored primary topic1.5/skill3.A; exact current repair source and curriculum checked','approval','APPROVAL-0194'), 'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid
from release_labels r join app.content_item_cells c on c.content_item_version_id=r.new_version_id and c.is_primary and c.superseded_by is null;
insert into app.content_taxonomy_validation_decisions(validation_decision_id,content_taxonomy_label_id,decided_by,decision,decision_source,reviewed_primary_unit,reviewed_required_units,notes)
select decision_id,label_id,'f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,'confirmed','automated_spot_check',1,array[1],'APPROVAL-0194 owner-authorized release: preserve authored topic1.5/skill3.A, histogram reading in Unit1; exact source and fresh independent QA checked.' from release_labels;
update app.content_taxonomy_labels l set label_status='validated',validated_by='f5a26c6b-3566-4d58-9e97-979fbb947564'::uuid,validated_at=now(),validation_decision_id=r.decision_id,validated_against_version_id=r.new_version_id,validated_against_taxo_hash=app.taxonomy_relevant_hash(r.new_version_id) from release_labels r where l.content_taxonomy_label_id=r.label_id;
